独立复核答案：

可执行的三比较交换如下：

~~~c
void Desc3(int *x,int *y,int *z){ int t;
 if(*x<*y){t=*x;*x=*y;*y=t;}
 if(*x<*z){t=*x;*x=*z;*z=t;}
 if(*y<*z){t=*y;*y=*z;*z=t;}
}
~~~

第一次使 x≥y，第二次使 x 不小于 z，第三次在剩余两数间排序，故结果 x≥y≥z。恰三次比较、最多三次交换，时间 O(1)、空间 O(1)。

独立核验答案（非原书摘录）：

令循环队列保存最近 k 项。边界为 m<0 或 k<2 时出错；0≤m<k−1 返回 0，m=k−1 返回 1。之后每次新项等于窗口和，并用“新和 = 旧和 + 新项 − 最旧项”维护。

~~~c
long long KFib(int k, int m) {
  if (k < 2 || m < 0) error();
  if (m < k-1) return 0;
  if (m == k-1) return 1;
  long long q[k], sum = 1; int front = 0;
  for (int i=0;i<k-1;i++) q[i]=0; q[k-1]=1;
  for (int i=k;i<=m;i++) {
    long long x=sum; sum += x-q[front]; q[front]=x; front=(front+1)%k;
  }
  return q[(front+k-1)%k];
}
~~~

循环不变式是 q 恰存放最近 k 项、sum 是它们之和，故新项满足定义；每轮 O(1)，总时间 O(m)，额外空间 O(k)。实际实现还应检查加法溢出。

独立核验答案（非原书摘录）：

不能先计算 (i!2^i) 再比较 MAXINT，因为乘法可能已经溢出。维护当前值 v=(i−1)!2^(i−1)，在乘 2i 前先判 (v>MAXINT/(2i))。

~~~c
Status Fill(long long a[], int arrsize, int n, long long MAXINT) {
  if (n<0 || n>arrsize) return ERROR;
  long long v=1;
  for (int i=1;i<=n;i++) {
    if (v > MAXINT/(2LL*i)) return OVERFLOW;
    v *= 2LL*i; a[i-1]=v;
  }
  return OK;
}
~~~

循环后 v=i!2^i，归纳可证；预判保证每次乘法安全。时间 O(n)，额外空间 O(1)。

