**完整答案**

只保留一个 rear 指针。非空时 rear 指向队尾数据结点，rear->next 永远指向头结点；空队时 rear 就指向头结点本身，且 rear->next==rear。因此不需要另存头指针。

~~~~c
typedef struct QNode {
    QElemType data;
    struct QNode *next;
} QNode;

Status InitQueue(QNode **rear) {
    *rear = (QNode *)malloc(sizeof(QNode));
    if (!*rear) return OVERFLOW;
    (*rear)->next = *rear;              /* rear 此时就是头结点 */
    return OK;
}

Status EnQueue(QNode **rear, QElemType e) {
    QNode *s = (QNode *)malloc(sizeof(QNode));
    if (!s) return OVERFLOW;
    s->data = e;
    s->next = (*rear)->next;            /* 新结点后接头结点 */
    (*rear)->next = s;                  /* 原队尾后接新结点 */
    *rear = s;
    return OK;
}

Status DeQueue(QNode **rear, QElemType *e) {
    QNode *head = (*rear)->next;        /* 临时取得头结点，不长期保存 */
    QNode *first = head->next;
    if (first == head) return ERROR;    /* 空队 */
    *e = first->data;
    head->next = first->next;
    if (first == *rear) {               /* 原队列只有一个数据结点 */
        *rear = head;
        head->next = head;
    }
    free(first);
    return OK;
}
~~~~

初始化、入队、出队均为 $O(1)$。销毁时从 rear->next 所指头结点开始释放整环即可。

